use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::collections::BTreeMap;

pub type Result<T> = std::result::Result<T, String>;

/// The positional array: trailing absent arguments are dropped; an absent one before a present one is refused,
/// since every handler reads its arguments by position (src/rpc/server.cpp transformNamedArguments for named ones).
pub fn positional(args: Vec<Option<Value>>) -> Result<Value> {
    let used = args.iter().rposition(Option::is_some).map_or(0, |i| i + 1);
    let mut params = Vec::with_capacity(used);
    for (i, arg) in args.into_iter().take(used).enumerate() {
        params.push(arg.ok_or_else(|| format!("argument {i} absent before a present one"))?);
    }
    Ok(Value::Array(params))
}

/// A reply outside the contract's type is an error naming the handler.
pub fn decode<T: serde::de::DeserializeOwned>(method: &str, reply: Value) -> Result<T> {
    serde_json::from_value(reply).map_err(|e| format!("{method}: reply outside the contract: {e}"))
}

