fn arg_i64(params: &Value, i: usize) -> Result<i64> {
    params[i]
        .as_i64()
        .ok_or_else(|| format!("argument {i}: not i64"))
}
fn opt_i64(params: &Value, i: usize) -> Result<Option<i64>> {
    params.get(i).map(|_| arg_i64(params, i)).transpose()
}
fn arg_f64(params: &Value, i: usize) -> Result<f64> {
    params[i]
        .as_f64()
        .ok_or_else(|| format!("argument {i}: not f64"))
}
fn arg_bool(params: &Value, i: usize) -> Result<bool> {
    params[i]
        .as_bool()
        .ok_or_else(|| format!("argument {i}: not bool"))
}
fn opt_bool(params: &Value, i: usize) -> Result<Option<bool>> {
    params.get(i).map(|_| arg_bool(params, i)).transpose()
}
fn arg_str(params: &Value, i: usize) -> Result<&str> {
    params[i]
        .as_str()
        .ok_or_else(|| format!("argument {i}: not a string"))
}
fn opt_str(params: &Value, i: usize) -> Result<Option<&str>> {
    params.get(i).map(|_| arg_str(params, i)).transpose()
}
fn arg_value(params: &Value, i: usize) -> Result<Value> {
    params
        .get(i)
        .cloned()
        .ok_or_else(|| format!("argument {i}: absent"))
}
fn opt_value(params: &Value, i: usize) -> Result<Option<Value>> {
    params.get(i).map(|_| arg_value(params, i)).transpose()
}

/// One handler called through its typed method from positional JSON arguments; the typed result re-serialized.
pub fn call_typed(node: &mut impl RpcContract, method: &str, params: &Value) -> Result<Value> {
    let typed = match method {
        "acceptblock" => {
            serde_json::to_value(node.acceptblock(arg_str(params, 0)?, opt_i64(params, 1)?)?)
        }
        "addToConfiscationTxidWhitelist" => {
            serde_json::to_value(node.add_to_confiscation_txid_whitelist(arg_value(params, 0)?)?)
        }
        "addToConsensusBlacklist" => {
            serde_json::to_value(node.add_to_consensus_blacklist(arg_value(params, 0)?)?)
        }
        "addToPolicyBlacklist" => {
            serde_json::to_value(node.add_to_policy_blacklist(arg_value(params, 0)?)?)
        }
        "generatetoaddress" => serde_json::to_value(node.generatetoaddress(
            arg_i64(params, 0)?,
            arg_str(params, 1)?,
            opt_i64(params, 2)?,
        )?),
        "getbestblockhash" => serde_json::to_value(node.getbestblockhash()?),
        "getblock" => {
            serde_json::to_value(node.getblock(arg_str(params, 0)?, opt_value(params, 1)?)?)
        }
        "getblockbyheight" => {
            serde_json::to_value(node.getblockbyheight(arg_i64(params, 0)?, opt_value(params, 1)?)?)
        }
        "getblockchainactivity" => serde_json::to_value(node.getblockchainactivity()?),
        "getblockcount" => serde_json::to_value(node.getblockcount()?),
        "getblockhash" => serde_json::to_value(node.getblockhash(arg_i64(params, 0)?)?),
        "getblockheader" => {
            serde_json::to_value(node.getblockheader(arg_str(params, 0)?, opt_value(params, 1)?)?)
        }
        "getchaintips" => serde_json::to_value(node.getchaintips()?),
        "getchaintxstats" => {
            serde_json::to_value(node.getchaintxstats(opt_i64(params, 0)?, opt_str(params, 1)?)?)
        }
        "getmempoolinfo" => serde_json::to_value(node.getmempoolinfo()?),
        "getmerkleproof" => {
            serde_json::to_value(node.getmerkleproof(arg_str(params, 0)?, opt_str(params, 1)?)?)
        }
        "getmerkleproof2" => serde_json::to_value(node.getmerkleproof2(
            arg_str(params, 0)?,
            arg_str(params, 1)?,
            opt_bool(params, 2)?,
            opt_str(params, 3)?,
            opt_str(params, 4)?,
        )?),
        "getnetworkinfo" => serde_json::to_value(node.getnetworkinfo()?),
        "getnewaddress" => serde_json::to_value(node.getnewaddress(opt_str(params, 0)?)?),
        "getorphaninfo" => serde_json::to_value(node.getorphaninfo()?),
        "getpeerinfo" => serde_json::to_value(node.getpeerinfo()?),
        "getrawmempool" => serde_json::to_value(node.getrawmempool(opt_bool(params, 0)?)?),
        "getrawnonfinalmempool" => serde_json::to_value(node.getrawnonfinalmempool()?),
        "getrawtransaction" => serde_json::to_value(
            node.getrawtransaction(arg_str(params, 0)?, opt_value(params, 1)?)?,
        ),
        "getreceivedbyaddress" => serde_json::to_value(
            node.getreceivedbyaddress(arg_str(params, 0)?, opt_i64(params, 1)?)?,
        ),
        "getsafemodeinfo" => serde_json::to_value(node.getsafemodeinfo()?),
        "gettransaction" => {
            serde_json::to_value(node.gettransaction(arg_str(params, 0)?, opt_bool(params, 1)?)?)
        }
        "gettxout" => serde_json::to_value(node.gettxout(
            arg_str(params, 0)?,
            arg_i64(params, 1)?,
            opt_bool(params, 2)?,
        )?),
        "gettxoutsetinfo" => serde_json::to_value(node.gettxoutsetinfo()?),
        "getwalletinfo" => serde_json::to_value(node.getwalletinfo()?),
        "ignoresafemodeforblock" => {
            serde_json::to_value(node.ignoresafemodeforblock(arg_str(params, 0)?)?)
        }
        "invalidateblock" => serde_json::to_value(node.invalidateblock(arg_str(params, 0)?)?),
        "preciousblock" => serde_json::to_value(node.preciousblock(arg_str(params, 0)?)?),
        "prioritisetransaction" => serde_json::to_value(node.prioritisetransaction(
            arg_str(params, 0)?,
            arg_f64(params, 1)?,
            arg_i64(params, 2)?,
        )?),
        "pruneblockchain" => serde_json::to_value(node.pruneblockchain(arg_i64(params, 0)?)?),
        "queryBlacklist" => serde_json::to_value(node.query_blacklist()?),
        "queryConfiscationTxidWhitelist" => {
            serde_json::to_value(node.query_confiscation_txid_whitelist(opt_bool(params, 0)?)?)
        }
        "reconsiderblock" => serde_json::to_value(node.reconsiderblock(arg_str(params, 0)?)?),
        "reconsidersafemodeforblock" => {
            serde_json::to_value(node.reconsidersafemodeforblock(arg_str(params, 0)?)?)
        }
        "sendrawtransaction" => serde_json::to_value(node.sendrawtransaction(
            arg_str(params, 0)?,
            opt_bool(params, 1)?,
            opt_bool(params, 2)?,
        )?),
        "sendrawtransactions" => {
            serde_json::to_value(node.sendrawtransactions(arg_value(params, 0)?)?)
        }
        "setban" => serde_json::to_value(node.setban(
            arg_str(params, 0)?,
            arg_str(params, 1)?,
            opt_i64(params, 2)?,
            opt_bool(params, 3)?,
        )?),
        "setmocktime" => serde_json::to_value(node.setmocktime(arg_i64(params, 0)?)?),
        "softrejectblock" => {
            serde_json::to_value(node.softrejectblock(arg_str(params, 0)?, arg_i64(params, 1)?)?)
        }
        "stop" => serde_json::to_value(node.stop()?),
        "submitblock" => {
            serde_json::to_value(node.submitblock(arg_str(params, 0)?, opt_value(params, 1)?)?)
        }
        "validateaddress" => serde_json::to_value(node.validateaddress(arg_str(params, 0)?)?),
        "verifychain" => {
            serde_json::to_value(node.verifychain(opt_i64(params, 0)?, opt_i64(params, 1)?)?)
        }
        "verifymerkleproof" => serde_json::to_value(
            node.verifymerkleproof(arg_value(params, 0)?, opt_str(params, 1)?)?,
        ),
        "verifyscript" => serde_json::to_value(node.verifyscript(
            arg_value(params, 0)?,
            opt_bool(params, 1)?,
            opt_i64(params, 2)?,
        )?),
        "waitforptvcompletion" => serde_json::to_value(node.waitforptvcompletion()?),
        _ => return Err(format!("{method}: not in the contract")),
    };
    typed.map_err(|e| format!("{method}: {e}"))
}

